import {escapeHtml as e} from './inventory.mjs';
const object=x=>{if(!x||typeof x!=='object'||Array.isArray(x))throw new Error('AI 盤點格式錯誤');return x;};
const text=x=>{if(x==null)return '';if(typeof x!=='string')throw new Error('AI 盤點文字格式錯誤');return x.slice(0,1500);};
const list=(x,max)=>{if(x==null)return [];if(!Array.isArray(x)||x.length>max)throw new Error('AI 盤點清單過大');return x;};
const number=x=>{if(x==null)return null;if(typeof x!=='number'||!Number.isFinite(x)||x<0)throw new Error('AI 盤點數值格式錯誤');return x;};
function packages(items){return list(items,10000).map(x=>{object(x);return {name:text(x.name),version:text(x.version),source:text(x.source),build:text(x.build)};});}
function packageTree(ai){return `<details class="usage-branch"><summary><span class="branch-title">Python / Conda 套件盤點</span><span class="usage-count">${ai.environments.reduce((sum,x)=>sum+(x.packages?.length??0),0).toLocaleString()} 筆（依環境）</span></summary><div class="branch-content">${ai.environments.map((x,index)=>`<details class="usage-branch ai-package-group" data-ai-index="${index}"><summary><span class="branch-title">${e(x.name)} · Python ${e(x.python)} · ${x.scope==='container'?'容器':'主機'}</span><span class="usage-count">${x.packages?.length??0} 筆</span></summary><div class="branch-content ai-package-content" data-loaded="false"></div></details>`).join('')}</div></details>`;}
export function mountAiPackages(panel,pc){if(!pc.ai)return;panel.addEventListener('toggle',event=>{const detail=event.target;if(!detail.matches('.ai-package-group')||!detail.open)return;const content=detail.querySelector(':scope > .ai-package-content');if(content.dataset.loaded==='true')return;const environment=pc.ai.environments[Number(detail.dataset.aiIndex)],items=environment?.packages??[];content.innerHTML='<label class="ai-package-search"><span>搜尋套件</span><input type="search" placeholder="套件名稱、版本或來源…" aria-label="搜尋環境套件"></label><div class="ai-package-results"></div>';const input=content.querySelector('input'),results=content.querySelector('.ai-package-results');const render=()=>{const query=input.value.toLowerCase().trim(),filtered=items.filter(x=>[x.name,x.version,x.source,x.build].some(v=>v.toLowerCase().includes(query)));results.innerHTML=filtered.length?`<div class="resource-scroll"><table class="resource-table"><thead><tr><th>套件</th><th>版本</th><th>來源</th><th>Build</th></tr></thead><tbody>${filtered.map(x=>`<tr><td>${e(x.name)}</td><td>${e(x.version)}</td><td>${e(x.source)}</td><td>${e(x.build||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="usage-note">沒有符合的套件，或此環境未提供套件清單。</p>';};input.oninput=render;content.dataset.loaded='true';render();},true);}
export function mergeAi(before,after){if(!after)return before??null;if(!before)return after;return Date.parse(before.collectedAt)>Date.parse(after.collectedAt)?before:after;}
export function normalizeAi(value){if(value==null)return null;object(value);if(!Number.isFinite(Date.parse(value.collectedAt)))throw new Error('AI 盤點時間格式錯誤');return {collectedAt:value.collectedAt,driverVersion:text(value.driverVersion),driverCuda:text(value.driverCuda),toolkits:list(value.toolkits,64).map(x=>{object(x);return {version:text(x.version),source:text(x.source),path:text(x.path)};}),environments:list(value.environments,512).map(x=>{object(x);if(x.cudaAvailable!=null&&typeof x.cudaAvailable!=='boolean')throw new Error('GPU 狀態格式錯誤');return {name:text(x.name),scope:x.scope==='container'?'container':'host',interpreter:text(x.interpreter),python:text(x.python),torchVersion:text(x.torchVersion),torchCuda:text(x.torchCuda),cudnn:number(x.cudnn),cudaAvailable:x.cudaAvailable??null,deviceCount:number(x.deviceCount),error:text(x.error),packages:packages(x.packages)};}),warnings:list(value.warnings,100).map(text)};}
const metric=(label,value)=>`<div><small>${e(label)}</small><strong>${e(value||'未取得')}</strong></div>`;
function cudaPackages(environment){const values=(environment.packages??[]).filter(x=>/^(cudatoolkit|cuda-version|cuda-cudart|cuda-toolkit|pytorch-cuda|cudnn|nvidia-cuda-runtime-cu\d+|nvidia-cudnn-cu\d+)$/.test(x.name));return values.length?`<small class="ai-cuda-packages">${values.map(x=>`${e(x.name)} ${e(x.version)}`).join('<br>')}</small>`:'';}
export function aiSummary(pc){const ai=pc.ai;if(!ai)return '';const versions=[...new Set(ai.environments.map(x=>x.torchVersion).filter(Boolean))];return `<section class="ai-summary"><div><strong>CUDA / PyTorch</strong><p>Toolkit ${e(ai.toolkits.map(t=>t.version).join(' / ')||'未偵測到')} <span>·</span> PyTorch ${e(versions.join(' / ')||'未偵測到可用安裝')}</p></div><button class="button" data-tab="system">查看環境 →</button></section>`;}
export function aiDetails(pc){const ai=pc.ai;if(!ai)return '<section class="ai-inventory"><h3>CUDA / PyTorch</h3><p class="usage-note">這台設備尚未完成 AI 環境盤點。</p></section>';const available=x=>x.cudaAvailable===true?`可用 · ${x.deviceCount??'—'} GPU`:x.cudaAvailable===false?'GPU 不可用':'未測得';
  return `<section class="ai-inventory"><div class="block-heading"><h3>CUDA / PyTorch 運算環境</h3><small>AI RUNTIME INVENTORY</small></div><div class="usage-metrics">${metric('NVIDIA 驅動版本',ai.driverVersion)}${metric('驅動回報的 CUDA 支援版本',ai.driverCuda)}${metric('已偵測 CUDA Toolkit',ai.toolkits.map(x=>x.version).join(' / '))}</div><p class="usage-note">驅動 CUDA 支援版本、已安裝 Toolkit、PyTorch 編譯 CUDA 分開列示。舊版驅動未回報 CUDA 支援版本時保留「未取得」。</p>${ai.toolkits.length?`<details class="usage-branch"><summary><span class="branch-title">CUDA Toolkit 安裝來源</span><span class="usage-count">${ai.toolkits.length} 個</span></summary><div class="branch-content"><dl class="usage-kv">${ai.toolkits.map(x=>`<div><dt>${e(x.version)} · ${e(x.source)}</dt><dd>${e(x.path)}</dd></div>`).join('')}</dl></div></details>`:''}<div class="resource-scroll"><table class="resource-table ai-table"><thead><tr><th>環境 / Python</th><th>PyTorch</th><th>PyTorch CUDA</th><th>cuDNN</th><th>GPU 測試</th></tr></thead><tbody>${ai.environments.map(x=>`<tr><td><strong>${e(x.name)}</strong><br><small>${x.scope==='container'?'容器':'主機'} · Python ${e(x.python)}</small></td><td>${e(x.torchVersion||'未取得')} ${x.error?`<details class="ai-error"><summary>檢查結果</summary><p>${e(x.error)}</p></details>`:''}</td><td>${e(x.torchCuda||(x.torchVersion?'CPU build':'未取得'))}${cudaPackages(x)}</td><td>${e(x.cudnn??'未取得')}</td><td><span class="ai-state ${x.cudaAvailable===false?'ai-unavailable':''}">${e(available(x))}</span></td></tr>`).join('')||'<tr><td colspan="5">未取得可執行的 Python 環境資料。</td></tr>'}</tbody></table></div>${packageTree(ai)}<p class="usage-note">盤點時間：${e(new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',dateStyle:'short',timeStyle:'medium'}).format(new Date(ai.collectedAt)))}（台北）。cuDNN 顯示 PyTorch 回報的原始版本碼。</p>${ai.warnings.length?`<details class="usage-branch"><summary><span class="branch-title">盤點範圍與限制</span></summary><div class="branch-content">${ai.warnings.map(x=>`<p class="usage-note">${e(x)}</p>`).join('')}</div></details>`:''}</section>`;
}
